extern "C" {
    fn printf(fmt: *const u8, ...) -> i32;
}

pub fn printf_results(count_a: i32, count_x: i32) {
    unsafe {
        let fmt = b"A: %d\n\0".as_ptr();
        printf(fmt, count_a);

        let fmt = b"x: %d\n\0".as_ptr();
        printf(fmt, count_x);
    }
}

